-- ----------------------------------------------
-- DEPOSIT_ACCOUNT
-- ----------------------------------------------
DROP TABLE IF EXISTS deposit_account;
CREATE TABLE deposit_account (
    account_id TEXT,
    cif TEXT,
    product_name TEXT,
    balance NUMERIC(24,6),
    currency TEXT,
    open_date DATE,
    maturity_date DATE,
    interest_rate NUMERIC(24,6),
    status TEXT,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    source_system TEXT,
    PRIMARY KEY (account_id)
);
CREATE INDEX idx_deposit_account_cif ON deposit_account(cif);
COMMIT;
